<body>
<div class="game">
  <header>
    <h1>Laundromat Sock Sort 🧺</h1>
    <div class="hud">
      <div class="pill">Score: <span id="score">0</span></div>
      <div class="pill">Pairs: <span id="pairs">0</span>/6</div>
      <div class="pill">Basket: <span id="basket">12</span></div>
    </div>
  </header>

  <p class="note">
    Match each sock to the washer with the same pattern. Drag/tap works, or use keyboard:
    <b>←/→</b> choose socks, <b>Enter</b> pick sock, <b>1-4</b> send to washer, <b>Esc</b> cancel.
  </p>

  <section class="machines" id="machines"></section>
  <section class="bin" id="bin" aria-label="Sock basket"></section>

  <div class="controls">
    <div class="message" id="message">Drag/tap a sock, or use ←/→ then Enter.</div>
    <button id="restart">New Basket</button>
  </div>
</div>

<div class="overlay" id="overlay">
  <div class="card">
    <h2>Basket Finished!</h2>
    <p id="final"></p>
    <button id="again">Sort Another Basket</button>
  </div>
</div>

<script>
const patterns = [
  {id:"dots", name:"Dots", icon:"●"},
  {id:"stripes", name:"Stripes", icon:"▨"},
  {id:"stars", name:"Stars", icon:"★"},
  {id:"zigzag", name:"Zigzag", icon:"〰"}
];

const bin = document.getElementById("bin");
const machines = document.getElementById("machines");
const scoreEl = document.getElementById("score");
const pairsEl = document.getElementById("pairs");
const basketEl = document.getElementById("basket");
const msg = document.getElementById("message");
const overlay = document.getElementById("overlay");
const final = document.getElementById("final");

let score, sorted, pairCounts, selectedSock, focusIndex, gameDone;

function shuffle(arr){
  return arr.map(v=>[Math.random(),v]).sort((a,b)=>a[0]-b[0]).map(v=>v[1]);
}

function liveSocks(){
  return [...document.querySelectorAll(".sock:not(.done)")];
}

function setMessage(text){
  msg.textContent = text;
}

function clearKeyboardFocus(){
  document.querySelectorAll(".kfocus").forEach(el=>el.classList.remove("kfocus"));
}

function focusSock(index){
  const socks = liveSocks();
  clearKeyboardFocus();
  if(!socks.length) return;
  focusIndex = ((index % socks.length) + socks.length) % socks.length;
  socks[focusIndex].classList.add("kfocus");
}

function selectSock(sock){
  document.querySelectorAll(".sock").forEach(x=>{
    x.classList.remove("selected");
    x.style.outline = "";
  });
  selectedSock = sock;
  sock.classList.add("selected");
  setMessage("Sock selected. Press 1-4 or tap the matching washer.");
}

function cancelSelection(){
  if(selectedSock) selectedSock.classList.remove("selected");
  selectedSock = null;
  clearKeyboardFocus();
  focusSock(focusIndex || 0);
  setMessage("Selection canceled. Choose another sock.");
}

function start(){
  score = 0;
  sorted = 0;
  focusIndex = 0;
  selectedSock = null;
  gameDone = false;
  pairCounts = {};
  patterns.forEach(p => pairCounts[p.id] = 0);
  scoreEl.textContent = score;
  pairsEl.textContent = 0;
  basketEl.textContent = 12;
  setMessage("Drag/tap a sock, or use ←/→ then Enter.");
  overlay.style.display = "none";
  renderMachines();
  renderSocks();
  focusSock(0);
}

function renderMachines(){
  machines.innerHTML = "";
  patterns.forEach((p,i)=>{
    const m = document.createElement("div");
    m.className = "machine";
    m.dataset.pattern = p.id;
    m.dataset.index = i;
    m.innerHTML = `<div class="keytag">${i+1}</div><div class="label">${p.name}</div><div class="door">${p.icon}</div><small>Drop ${p.name} socks here</small>`;
    m.addEventListener("dragover", e=>{e.preventDefault();m.classList.add("over")});
    m.addEventListener("dragleave", ()=>m.classList.remove("over"));
    m.addEventListener("drop", e=>{
      e.preventDefault();
      m.classList.remove("over");
      const id = e.dataTransfer.getData("text/plain");
      const sock = document.getElementById(id);
      if(sock) dropSock(sock,m);
    });
    m.addEventListener("click", ()=> {
      if(selectedSock) dropSock(selectedSock,m);
      else setMessage("Pick a sock first, then choose a washer.");
    });
    machines.appendChild(m);
  });
}

function renderSocks(){
  bin.innerHTML = "";
  let socks = [];
  let n = 0;
  for(let i=0;i<6;i++){
    const p = patterns[i % patterns.length];
    socks.push({pattern:p.id, id:"sock"+(++n)});
    socks.push({pattern:p.id, id:"sock"+(++n)});
  }
  shuffle(socks).forEach(s=>{
    const sock = document.createElement("div");
    sock.id = s.id;
    sock.className = `sock ${s.pattern}`;
    sock.dataset.pattern = s.pattern;
    sock.draggable = true;
    sock.setAttribute("role","button");
    sock.setAttribute("tabindex","0");
    sock.setAttribute("aria-label",`${s.pattern} sock`);
    sock.textContent = "🧦";
    sock.addEventListener("dragstart", e=>e.dataTransfer.setData("text/plain",sock.id));
    sock.addEventListener("click", ()=>{
      const socks = liveSocks();
      focusIndex = Math.max(0, socks.indexOf(sock));
      focusSock(focusIndex);
      selectSock(sock);
    });
    sock.addEventListener("keydown", e=>{
      if(e.key === "Enter" || e.key === " "){
        e.preventDefault();
        selectSock(sock);
      }
    });
    bin.appendChild(sock);
  });
}

function dropSock(sock,machine){
  if(gameDone || !sock || sock.classList.contains("done")) return;

  const correct = sock.dataset.pattern === machine.dataset.pattern;

  if(correct){
    score += 10;
    sorted++;
    pairCounts[sock.dataset.pattern]++;
    sock.classList.add("done");
    sock.classList.remove("selected","kfocus");
    sock.style.outline = "";
    selectedSock = null;
    setMessage(pairCounts[sock.dataset.pattern] % 2 === 0 ? "Pair matched! Fresh laundry win." : "Good drop. Find its twin.");
    focusSock(focusIndex);
  } else {
    score = Math.max(0, score - 5);
    machine.classList.add("bad");
    setTimeout(()=>machine.classList.remove("bad"),260);
    setMessage("Wrong machine. Minus 5. Sock is still in the basket.");
  }

  scoreEl.textContent = score;
  pairsEl.textContent = Math.floor(sorted/2);
  basketEl.textContent = 12 - sorted;

  if(sorted === 12) finish();
}

function finish(){
  gameDone = true;
  const penaltyFree = score === 120;
  final.innerHTML = `Final score: <b>${score}</b><br>Pairs finished: <b>6</b><br>${penaltyFree ? "Perfect basket. Every sock found its washer." : "Basket done. Cleaner sorting means a higher score."}`;
  overlay.style.display = "grid";
}

document.addEventListener("keydown", e=>{
  if(gameDone){
    if(e.key === "Enter" || e.key === " "){
      e.preventDefault();
      start();
    }
    return;
  }

  const socks = liveSocks();

  if(e.key === "ArrowRight" || e.key === "ArrowDown"){
    e.preventDefault();
    focusSock((focusIndex || 0) + 1);
    setMessage("Sock focus moved. Press Enter to pick it.");
  }

  if(e.key === "ArrowLeft" || e.key === "ArrowUp"){
    e.preventDefault();
    focusSock((focusIndex || 0) - 1);
    setMessage("Sock focus moved. Press Enter to pick it.");
  }

  if(e.key === "Enter" || e.key === " "){
    if(overlay.style.display === "grid") return;
    e.preventDefault();
    if(selectedSock){
      setMessage("Sock already selected. Press 1-4 to choose a washer.");
    } else if(socks.length){
      selectSock(socks[focusIndex || 0]);
    }
  }

  if(["1","2","3","4"].includes(e.key)){
    e.preventDefault();
    const machine = document.querySelector(`.machine[data-index="${Number(e.key)-1}"]`);
    if(selectedSock && machine){
      machine.classList.add("targeted");
      setTimeout(()=>machine.classList.remove("targeted"),180);
      dropSock(selectedSock,machine);
    } else {
      setMessage("Choose a sock first with ←/→ and Enter.");
    }
  }

  if(e.key === "Escape"){
    e.preventDefault();
    cancelSelection();
  }
});

document.getElementById("restart").onclick = start;
document.getElementById("again").onclick = start;
start();
</script>
</body>
</html>
